const LOTES=[{"codigo":"sjc-tecnico-2025","ano":2025,"cargo":"Assistente Técnico em Saúde — Técnico de Enfermagem","orgao":"Prefeitura de São José dos Campos","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/assistente-tecnico-em-saude-tecnico-de-enfermagemcnm101-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/gabarito-definitovo-prefeitura-de-sjc.pdf","itens":[{"n":1,"disciplina":"Língua Portuguesa","tema":"Semântica e Significação","enunciado":"As frases abaixo se estruturam com base numa duplicidade de sentidos de um vocábulo ou expressão, com exceção de uma . Assinale-a.","alternativas":["Aquele homem e o coração dele não batem bem.","Estou na meia-idade, difícil vai ser a idade inteira.","Já que a primeira impressão é a que fica, use uma impressora laser!","Não sei se Jesus tinha a Internet em mente quando disse a seus incrédulos discípulos que lançassem suas redes ao mar.","Quando tudo mais falhar, leia o manual de instruções"],"gabarito":"E"},{"n":3,"disciplina":"Língua Portuguesa","tema":"Figuras de Linguagem e Vícios de Linguagem","enunciado":"Em todas as frases abaixo há comparações. Assinale a frase em que a comparação é empregada sem explicações.","alternativas":["A ópera é como uma ostra, que deve: ou ser engolida inteira, ou não engolida de jeito nenhum.","A vida é como uma peça teatral, só que no teatro os diálogos são melhores.","Para mim, solo de guitarra é como o latim, uma língua morta.","Ler Proust é como arar um campo com agulha de crochê, demorado.","Brasília é como uma colmeia de abelhas: metade fica voando, metade fazendo cera"],"gabarito":"B"},{"n":4,"disciplina":"Língua Portuguesa","tema":"Interpretação de Textos","enunciado":"Leia com atenção o texto abaixo. Não há nada tão inverossímil como os acontecimentos da vida real. Leiam, no mesmo jornal, as notícias várias e, logo a seguir, um romance. Verão que o romance é sempre muito claro e muito explicável; tudo o que nele acontece tem uma razão de ser. Mas, das notícias várias, nove em dez são absolutamente incompreensíveis, enquanto um romancista não as retoma para as explicar. Assinale a afirmativa correta em relação à sua estruturação e significação.","alternativas":["Para que a vida real fosse explicada, seria necessário que seus fatos fossem publicados nos jornais.","O texto critica a linguagem dos jornais, que não torna explicáveis os fatos da vida real.","O romance é mais claro que o jornal por não ter compromissos com a verdade.","O modo de fazer com que os fatos da vida real se tornem explicáveis, é inseri-los num romance.","Jornal e romances mostram uma coisa em comum: a incapacidade de explicar a vida"],"gabarito":"D"},{"n":6,"disciplina":"Língua Portuguesa","tema":"Pontuação","enunciado":"Assinale a frase a seguir em que o uso de dois -pontos (:) está empregado por preceder um esclarecimento.","alternativas":["Existem duas classes de escritores geniais: os que pensam e os que fazem pensar.","Há dois tipos de pedestres: os rápidos e os atropelados.","Só há uma coisa pior do que ser objeto de falatórios: é não sê- lo.","Quando era jovem me diziam: “Você vai ver quando tiver 50 anos”. Tenho 50 anos e ainda não vi nada.","A obra de arte: uma interrupção do tempo"],"gabarito":"C"},{"n":7,"disciplina":"Língua Portuguesa","tema":"Classes de Palavras","enunciado":"Observe a seguinte frase: A pessoa a quem entregaram a medalha, foi a que a homenageou no discurso de encerramento. Nessa frase há cinco ocorrências do vocábulo “a”, que pertencem a quatro classes gramaticais. Assinale a única classe ausente dessa frase.","alternativas":["Pronome demonstrativo.","Pronome pessoal.","Preposição.","Substantivo.","Artigo definido"],"gabarito":"D"},{"n":8,"disciplina":"Língua Portuguesa","tema":"Funções da Linguagem","enunciado":"Assinale a frase que mostra a função de linguagem predominante nela indicada de forma correta.","alternativas":["“Cocota” é um outro nome que se dá à maritaca. / informativa ou referencial.","Bom dia! Como vai? / fática.","Guimarães Rosa é originário de Minas Gerais. / conativa.","Preste atenção ao que está lendo! / emotiva.","Estou com enorme dor de dente! / metalinguística."],"gabarito":"B"},{"n":9,"disciplina":"Língua Portuguesa","tema":"Ortografia e Acentuação","enunciado":"Observe o seguinte texto: Ontem à tarde, por 2 kms. na Ave. Copacabana, ocorreu uma passeata que parecia do séc. passado: pessoas de vários gên. desfilaram, durante 2h. com roupas de época durante 2h. Descobriu-se, depois, que se tratava de propaganda de uma loja de roupas que se havia inaugurado no centro do R. de Janeiro. O texto mostra uma série de abreviaturas. Abaixo estão várias normas para a abreviação. Entre elas, assinale a única que foi obedecida.","alternativas":["Não se devem abreviar nomes geográficos.","Símbolos científicos devem ser abreviados sem ponto.","Formas abreviadas devem terminar em consoante.","As formas abreviadas devem manter o acento gráfico.","Formas de medidas não mostram plural na abreviatura"],"gabarito":"D"},{"n":11,"disciplina":"Língua Portuguesa","tema":"Ortografia e Acentuação","enunciado":"Assinale a frase a seguir em que o vocábulo “abaixo -assinado” deveria estar grafado sem hífen.","alternativas":["O abaixo-assinado foi encaminhado ao governador.","Os abaixo-assinados eram acompanhados de documentos.","Todos os abaixo-assinados pertencem à classe militar.","Todos os abaixo-assinados estão redigidos em inglês.","Todas as reivindicações estavam no abaixo-assinado"],"gabarito":"C"},{"n":12,"disciplina":"Língua Portuguesa","tema":"Crase","enunciado":"Assinale a frase em que houve troca indevida entre A/À/HÁ.","alternativas":["Toda semana o senador vai à Brasília.","Os turistas foram inicialmente a Portugal.","A excursão ocorrerá daqui a duas semanas.","O museu foi restaurado há pouco tempo.","Nunca mais voltaremos à Rússia"],"gabarito":"A"},{"n":13,"disciplina":"Língua Portuguesa","tema":"Semântica e Significação","enunciado":"Assinale a afirmativa que apresenta o uso de parônimos.","alternativas":["O desgosto do suor traz o prazer da recompensa.","O estudo precedente carrega o argumento procedente.","O veículo mais sonhado, pelos clientes, é o carro.","O conserto de minha máquina fotográfica será para registrar o concerto no Teatro Municipal.","Mudar as leis faz modificar, também, a sociedade"],"gabarito":"B"},{"n":14,"disciplina":"Língua Portuguesa","tema":"Tipos de Discurso","enunciado":"Assinale a afirmativa em que ocorre o discurso indireto livre.","alternativas":["O livro foi fechado, a luz foi apagada. O descanso é necessário. Amanhã, vou aproveitar o dia, eu sinto!","Platão afirmou: “Uma vida não examinada não merece ser vivida.”.","O menino fala sobre felicidade como quem tem a experiência de uma longa caminhada.","O adolescente pensou, pensou, mas decidiu seguir a carreira que lhe traria maior felicidade.","“Só há um caminho para a felicidade. Não nos preocuparmos com coisas que ultrapassam o poder de nossa vontade.”, filosofou Epicuro"],"gabarito":"A"},{"n":15,"disciplina":"Língua Portuguesa","tema":"Estrutura e Formação de Palavras","enunciado":"A respeito do uso dos estrangeirismos em nossa língua, assinale a opção que estabelece a relação adequada entre o exemplo de estrangeirismo e sua origem correspondente:","alternativas":["buffet: anglicismo.","a priori: galicismo.","menu: latinismo.","outdoor: anglicismo.","show: galicismo. Raciocínio Lógico Matemático"],"gabarito":"D"},{"n":16,"disciplina":"Raciocínio Lógico e Matemática","tema":"Conjuntos","enunciado":"Um conjunto A possui 20 elementos e um conjunto B possui 15 elementos. O número de elementos da união dos conjuntos A e B é, no mínimo,","alternativas":["15.","20.","25.","30.","35."],"gabarito":"B"},{"n":18,"disciplina":"Raciocínio Lógico e Matemática","tema":"Equações e Sistemas","enunciado":"Ana faz aniversário em janeiro e Bia faz aniversário em março. Em maio de 2025, Bia tinha 2 anos a mais que Ana e a soma das idades delas era de 22 anos. Considerando a idade de uma pessoa como o número de anos completos, em fevereiro de 2032 a soma das idades de Ana e Bia será de","alternativas":["29 anos.","34 anos.","35 anos.","36 anos.","37 anos"],"gabarito":"C"},{"n":19,"disciplina":"Raciocínio Lógico e Matemática","tema":"Razão, Proporção e Porcentagem","enunciado":"O comprimento de uma volta completa na pista do autódromo de Interlagos é de 4.310 metros. Um carro de corrida completou uma volta nessa pista em 1 minuto e 20 segundos. A velocidade média do carro nessa volta, em quilômetros por hora, foi de, aproximadamente,","alternativas":["166 km/h.","172 km/h.","180 km/h.","188 km/h.","194 km/h"],"gabarito":"E"},{"n":20,"disciplina":"Raciocínio Lógico e Matemática","tema":"Argumentação Lógica","enunciado":"Miguel é um garoto que sempre mente. Miguel tem várias camisetas e, certo dia, vestiu uma delas para sair e caminhar. Ao sair de casa, disse ao porteiro: “Eu tenho uma camiseta que não é branca”. Nesse caso, é correto concluir que","alternativas":["todas as camisetas de Miguel são brancas.","Miguel tem apenas uma camiseta branca.","Miguel tem apenas uma camiseta e ela não é branca.","Miguel tem pelo menos duas camisetas que não são brancas.","Miguel não tem nenhuma camiseta branca"],"gabarito":"A"},{"n":21,"disciplina":"Raciocínio Lógico e Matemática","tema":"Matemática Financeira","enunciado":"Um estacionamento rotativo cobra 15 reais pela primeira hora, 12 reais pela segunda hora e 8 reais por cada hora seguinte. O estacionamento esclarece que qualquer fração de hora é cobrada pela hora inteira. João entrou com seu carro nesse estacionamento às 10h20min de certo dia e saiu às 15h45min. Nesse caso, João pagou a seguinte quantia pelo período estacionado:","alternativas":["32 reais.","48 reais.","51 reais.","55 reais.","59 reais"],"gabarito":"E"},{"n":22,"disciplina":"Raciocínio Lógico e Matemática","tema":"Sequências e Padrões","enunciado":"Em certo país imaginário e isolado do mundo, o autoritário rei vai abolir t odos os domingos a partir do ano de 2026. Assim, cada semana desse país no próximo ano terá apenas seis dias. O ano de 2026 não será bissexto e o dia 1º de janeiro será uma quinta-feira. Nesse país, o último dia do ano de 2026 será","alternativas":["uma segunda-feira.","uma terça-feira.","uma quarta-feira.","uma sexta-feira.","um sábado"],"gabarito":"B"},{"n":23,"disciplina":"Raciocínio Lógico e Matemática","tema":"Análise Combinatória","enunciado":"Em uma fila de poltronas de um cinema há 6 poltronas vazias em sequência: Os irmãos André e Bruno e as amigas Maria, Nina e Paula vão ocupar 5 desses 6 lugares. Entretanto, as amigas querem se sentar juntas, ou seja, uma ao lado da outra. O número de maneiras diferentes em que as 5 pessoas podem se sentar é igual a","alternativas":["96.","120.","144.","180.","216."],"gabarito":"C"},{"n":24,"disciplina":"Raciocínio Lógico e Matemática","tema":"Probabilidade","enunciado":"Em uma caixa há duas bolas bran cas, duas bolas pretas e duas bolas vermelhas, todas do mesmo peso e tamanho. São retiradas, aleatoriamente, duas bolas. A probabilidade de que essas bolas sejam de cores diferentes é de","alternativas":["60%.","72%.","75%.","80%.","90%"],"gabarito":"D"},{"n":25,"disciplina":"Raciocínio Lógico e Matemática","tema":"Argumentação Lógica","enunciado":"Fernando, Gilberto e Hugo são funcionários da prefeitura. Um é médico, outro é contador e outro é diretor. São verdadeiras as afirmações: • Fernando é mais velho do que o contador. • Gilberto é médico. • Hugo não é o mais novo. Nesse caso, é correto afirmar que","alternativas":["Fernando é o contador.","o médico é mais velho do que Hugo.","Hugo é mais velho do que o diretor.","o médico não é Gilberto.","o diretor é mais velho do que Gilberto. Atualidades"],"gabarito":"E"},{"n":31,"disciplina":"Legislação do SUS","tema":"Lei 8.080/1990 - Princípios e Diretrizes","enunciado":"O Art. 7º da Lei 8.080/1990 estabelece que as ações e serviços públicos de saúde e os serviços privados contratados ou conveniados que integram o Sistema Único de Saúde (SUS), são desenvolvidos de acordo com as diretrizes previstas no art. 198 da Constituição Federal , e que devem obedecer a determinados princípios. Avalie se tais princípios incluem: I. universalidade de acesso aos serviços de saúde em todos os níveis de assistência. II. integralidade de assistência, entendida como conjunto articulado e cont ínuo das ações e serviços preventivos e curativos, individuais e coletivos, exigidos para cada caso em todos os níveis de complexidade do sistema. III. igualdade da assistência à saúde, sem preconceitos ou privilégios de qualquer espécie. IV. utilização da epidemiologia para o estabelecimento de prioridades, a alocação de recursos e a orientação programática. Estão corretos os itens","alternativas":["I e II, apenas.","III e IV, apenas.","I, II e III, apenas.","II, III e IV, apenas.","I, II, III e IV"],"gabarito":"E"},{"n":32,"disciplina":"Legislação do SUS","tema":"Telessaúde no SUS","enunciado":"A telessaúde pode ser entendida como “a modalidade de prestação de serviços de saúde à distância, por meio da utilização das tecnologias da informação e da comunicação, que envolve, entre outros, a transmissão segura de dados e informações de saúde, por meio de textos, de sons, de imagens ou outras formas adequadas.” O Art. 26-A da Lei 8.080/1990 estabelece que a telessaúde abrange a prestação remota de serviços relacionados a todas as profissões da área da saúde regulamentadas pelos órgãos competentes do Poder Executivo federal e obedecerá aos seguintes princípios , entre outros, à exceção de um. Assinale-o.","alternativas":["Autonomia do profissional de saúde.","Consentimento livre e informado do paciente.","Direito de recusa ao atendimento na modalidade telessaúde, com a garantia do atendimento presencial sempre que solicitado.","Inconfidencialidade dos dados.","Responsabilidade digital"],"gabarito":"D"},{"n":33,"disciplina":"Enfermagem","tema":"Atenção Primária à Saúde","enunciado":"A Atenção Básica caracteriza -se por um conjunto de ações de saúde, no âmbito individual e coletivo, que abrangem a promoção e a proteção da saúde, a prevenção de agravos, o diagnóstico, o tratamento, a reabilitação e a manutenção da saúde. Acerca da Atenção Básica, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A Atenção Básica considera o sujeito em sua singularidade, na complexidade, na integralidade e na inserção sociocultural e busca a promoção de sua saúde, a prevenção e tratamento de doenças e a redução de danos ou de sofrimentos que possam comprometer suas possibilidades de viver de modo saudável. ( ) A Atenção Básica tem a Saúde da Família como estratégia prioritária para sua organização de acordo com os preceitos do Sistema Único de Saúde. ( ) Um fundamento da Atenção Básic a é possibilitar o acesso universal e contínuo a serviços de saúde de qualidade e resolutivos, caracterizados como a porta de entrada preferencial do sistema de saúde, com território adscrito de forma a permitir o planejamento e a programação descentralizada, e em consonância com o princípio da equidade. As afirmativas são, respectivamente,","alternativas":["V – V – V.","V – F – V.","F – V – F.","F – V – V.","V – F – F"],"gabarito":"A"},{"n":34,"disciplina":"Enfermagem","tema":"Segurança do Paciente","enunciado":"De acordo com a RDC nº 63, de 25 de novembro de 2011, que dispõe sobre os requisitos de boas práticas de funcionamento para os Serviços de Saúde, a “ totalidade das ações sistemáticas necessárias para garantir que os serviços prestados estejam dentro dos padrões de qualidade exigidos, para os fins a que se propõem” conceitua","alternativas":["integralidade do atendimento.","garantia da qualidade.","humanização da atenção.","segurança do paciente.","gestão da saúde."],"gabarito":"B"},{"n":35,"disciplina":"Legislação do SUS","tema":"Constituição Federal - Saúde","enunciado":"O Art. 194 da Constituição Federal de 1988 estabelece que a seguridade social compreende um conjunto integrado de ações de iniciativa dos Poderes Públicos e da sociedade, destinadas a assegurar os direitos relativos à saúde, à previdência e à assistência social. Para tanto, avalie, com base no referido artigo constitucional, se compete ao Poder P úblico, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos: I. universalidade da cobertura e do atendimento. II. uniformidade e equivalência dos benefícios e serviços às populações urbanas e rurais. III. seletividade e distr ibutividade na prestação dos benefícios e serviços. IV. irredutibilidade do valor dos benefícios. Estão corretos os itens","alternativas":["I e II, apenas.","III e IV, apenas.","I, II e III, apenas.","II, III e IV, apenas.","I, II, III e IV. Técnico de Enfermagem"],"gabarito":"E"},{"n":36,"disciplina":"Enfermagem","tema":"Fundamentos e Semiotécnica","enunciado":"O osso ímpar, localizado na parte posterior, formando a base do crânio, é denominado","alternativas":["parietal.","etmoide.","occipital.","temporal.","esfenoide"],"gabarito":"C"},{"n":37,"disciplina":"Enfermagem","tema":"Fundamentos e Semiotécnica","enunciado":"Com base na anatomia e fisiologia do sistema urinário, é correto afirmar que","alternativas":["os rins têm como função principal armazenar a urina e regular a temperatura do corpo.","os ureteres são tubos musculares que transportam a urina dos rins para a bexiga por meio de movimentos peristálticos.","a bexiga urinária é responsável pela produção de urina e secreção de hormônios como a renina.","a uretra conduz a urina dos rins diretamente ao meio externo, sendo mais longa nas mulheres.","a filtração do sangue ocorre exclusi vamente na bexiga, onde os resíduos são eliminados"],"gabarito":"B"},{"n":38,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Durante o atendimento a um paciente em Unidade de Pronto Atendimento, o profissional de saúde observa os seguintes sinais e sintomas: confusão mental, pele fria e pegajosa, sudorese intensa, palidez, taquicardia e hipotensão. Esses sinais são sugestivos de","alternativas":["choque potencialmente grave.","hiperglicemia leve, sem risco imediato.","acidente vascular cerebral hemorrágico.","ansiedade leve, com manifestações psicossomáticas.","crise hipertensiva controlada, sem necessidade de intervenção imediata"],"gabarito":"A"},{"n":39,"disciplina":"Enfermagem","tema":"Fundamentos e Semiotécnica","enunciado":"Com base nos protocolos e fundamentos acerca das técnicas básicas de enfermagem na rotina assistencial, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Na medição da pressão arterial pela técnica auscultatória, o manguito deve ser inflado rapidamente até ultrapassar 20 a 30 mmHg o nível estimado da PA sistólica. ( ) O pulso tibial posterior deve ser verificado ao lon go da parte superior do pé, entre os tendões de extensão do hálux. ( ) A bradipneia é caracterizada por uma frequência respiratória lenta e superficial, abaixo de 12 respirações por minuto em repouso. As afirmativas são, respectivamente,","alternativas":["F – V – F.","V – V – V.","F – F – F.","V – F – V.","F – V – V"],"gabarito":"D"},{"n":40,"disciplina":"Enfermagem","tema":"Fundamentos e Semiotécnica","enunciado":"Com base nos protocolos e orientações relacionadas à oxigenoterapia e aspiração das vias aéreas, é correto afirmar que","alternativas":["a cânula nasal de oxigênio permite fornecer concentrações moderadas de oxigênio a um fluxo máximo de 10 L/min.","a máscara de Venturi é contraindicada para pacientes com DPOC devido à entrega controlada de oxigênio.","a saturação de oxigênio normal em adultos saudáveis varia entre 85% a 90% em repouso.","a aspiração de vias aéreas deve ser realizada por, no máximo, 10 a 15 segundos por tentativa, com técnica asséptica e intervalo entre tentativas.","a administração de oxigênio por máscara não reinalante é contraindicada para crianças menores de cinco anos"],"gabarito":"D"},{"n":41,"disciplina":"Enfermagem","tema":"Imunização","enunciado":"Considerando os mecanismos de defesa do organismo humano e os tipos de imunidade, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A imunidade inata é adquirida ao longo da vida por meio de exposições a agentes infecciosos ou pela vacinação. ( ) A imunidade ativa pode ser adquirida naturalmente, por meio de infecção, ou artificialmente, por meio da vacinação. ( ) A imunidade passiva confere proteção duradoura, pois envolve a produção de memória imunológica. As afirmativas são, respectivamente,","alternativas":["F – V – F.","V – V – V.","F – F – F.","V – F – V.","F – V – V."],"gabarito":"A"},{"n":42,"disciplina":"Enfermagem","tema":"Hipertensão Arterial","enunciado":"Com base nos protocolos do Ministério da Saúde e da Sociedade Brasileira de Cardiologia, assinale a afirmat iva que corresponde a uma recomendação de assistência a pacientes com distúrbios cardiovasculares.","alternativas":["Pacientes com IAM devem permanecer em repouso absoluto por pelo menos 7 dias para garantir completa recuperação do miocárdio.","A administração de oxigênio é obrigatória para todos os pacientes com IAM, independentemente dos níveis de saturação.","Deve-se monitorar a pressão arterial e a frequência cardíaca após a administração de betabloqueadores em pacientes com IAM, devido ao risco de bradicardia ou hipotensão excessiva.","A elevação da cabeceira é contraindicada em pacientes com edema agudo de pulmão decorrente de insuficiência cardíaca.","O ECG deve ser realizado imediatamente, em até 15 minutos após a chegada do paciente a o serviço de saúde , sendo essencial para o diagnóstico e decisão terapêutica"],"gabarito":"C"},{"n":43,"disciplina":"Enfermagem","tema":"Centro de Material e Esterilização (CME)","enunciado":"De acordo com as disposições do Ministério da Saúde acerca do processamento de produtos para a saúde, é correto afirmar que","alternativas":["a limpeza é uma etapa obrigatória e indispensável antes da desinfecção ou esterilização de produtos para saúde.","o reprocessamento de produtos para saúde de uso único é permitido em situações de emergência.","a rastreabilidade dos produtos esterilizados é exigida apenas em procedimentos cirúrgicos de grande porte.","a validação dos processos de esterilização é facultativa, sendo obrigatória somente quando houver suspeita de falha no processo.","a classificação dos artigos em críticos, semicríticos e não críticos é irrelevante para a definição do tipo de processamento a ser realizado"],"gabarito":"A"},{"n":44,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"De acordo com as recomendações do Ministério da Saúde, a frequência cardíaca materna no primeiro período do trabalho de parto de uma parturiente de 30 anos, de risco hab itual, deve ser verificada e registrada na seguinte frequência:","alternativas":["de uma em uma hora.","de duas em duas horas.","a cada 4 horas.","a cada 15 minutos.","a cada 30 minutos"],"gabarito":"A"},{"n":45,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"Com base nos protocolos acerca dos cuidados imediatos que devem ser dispensados ao recém -nascido (RN), avalie as afirmativas a seguir. I. O banho do recém-nascido deve ser realizado imediatamente após o nascimento para remover o vérnix caseoso e prevenir infecções. II. A administração de vitamina K intramuscular não é necessária em recém -nascidos a termo, pois eles possuem reservas adequadas dessa vitamina. III. Em recém-nascidos com peso inferior a 2 Kg, a vacina BCG deve ser adiada até que eles atinjam o peso adequado. Está correto o que se afirma em","alternativas":["I, II e III.","I, apenas.","II, apenas.","III, apenas.","I e II, apenas"],"gabarito":"D"},{"n":46,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"Com base nos parâmetros do Ministério da Saúde relacionados à frequência cardíaca e frequência respiratória em crianças, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Em crianças de 1 a 2 anos, a frequência cardíaca normal em repouso varia entre 60 e 80 batimentos por minuto. ( ) A frequência respiratória normal em lactentes de 2 a 12 meses é de até 60 incursões respiratórias por minuto. ( ) Em crianças de 1 a 4 anos, uma frequência respiratória de até 50 incursões por minuto é considerada normal. As afirmativas são, respectivamente,","alternativas":["F – V – V.","V – V – V.","F – V – F.","V – F – V.","F – F – F"],"gabarito":"E"},{"n":47,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"Após o parto a mulher deve ser orientada sobre os cuidados e recomendações relacionadas ao puerpério. Nesse sentido, com base nos protocolos do Ministério da Saúde, é correto afirmar que","alternativas":["a primeira consulta pós -parto deve ocorrer entre 7 e 10 dias após a alta hospitalar, com retorno até 42 dias, para monitorar a saúde da mãe e do recém-nascido.","os lóquios desaparecem completamente até o terceiro dia pós- parto, e qualquer sangramento após esse período é considerado anormal.","a amame ntação deve ser iniciada apenas após a descida completa do leite, geralmente no terceiro dia pós -parto, para evitar desconfortos mamários.","a mulher no puerpério deve evitar qualquer forma de atividade física até completar 90 dias após o parto, para garantir a recuperação adequada.","durante o puerpério, não é necessário abordar o planejamento reprodutivo, pois a fertilidade só retorna após o término da amamentação exclusiva."],"gabarito":"A"},{"n":48,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"De acordo com a Cadeia de Sobrevivência da American Heart Association para PCR em ambiente intra -hospitalar – PCRIH de pacientes adultos, é correto afirmar que","alternativas":["a desfibrilação deve ser realizada imediatamente, antes da RCP de alta qualidade.","a cadeia de sobrevivência só deve ser utilizada para pacientes que apresentem ritmo chocável.","a RCP de alta qualidade compreende, entre outras coisas, 100 a 120 compressões cardíacas por minuto.","os cuidados pós -PCR não são incluídos nesta cadeia, pois o paciente já está sendo monitorado.","a ressuscitação avançada é o principal elo da cadeia de sobrevivência para a PCRIH"],"gabarito":"C"},{"n":49,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Um paciente atendido na Unidade de Pronto Atendimento apresentou, entre outros sinais e sintomas, temperatura = 26°C. Esse valor corresponde a","alternativas":["estresse por frio.","hipotermia leve.","hipotermia grave.","hipotermia profunda.","hipotermia moderada"],"gabarito":"C"},{"n":50,"disciplina":"Enfermagem","tema":"Saúde do Trabalhador","enunciado":"Um profissional de saúde que trabalha com radiação não ionizante está exposto a risco ambiental","alternativas":["físico.","químico.","biológico.","acidental.","ergonômico"],"gabarito":"A"},{"n":51,"disciplina":"Enfermagem","tema":"Controle de Infecção e Biossegurança","enunciado":"Com base nas normas e protocolos do Ministério da Saúde, uma doença com indicação de isolamento do paciente durante o tratamento é","alternativas":["a dengue.","a rubéola.","o tétano.","a hepatite B.","a hanseníase"],"gabarito":"B"},{"n":52,"disciplina":"Enfermagem","tema":"Imunização","enunciado":"De acordo com as normas do Ministério da Saúde, a vacina tríplice viral – SRC é contraindicada para o seguinte grupo, mesmo em situações de surto de sarampo, caxumba ou rubéola:","alternativas":["idosos.","gestantes.","portadores de HIV.","mulheres em idade fértil.","crianças menores de 15 meses"],"gabarito":"B"},{"n":53,"disciplina":"Enfermagem","tema":"Imunização","enunciado":"Conforme orientações do Ministério da Saúde, os diluentes devem ser mantidos refrigerados por pelo menos","alternativas":["6 horas antes de serem utilizados para diluição da vacina.","8 horas antes de serem utilizados para diluição da vacina.","12 horas antes de serem utilizados para diluição da vacina.","15 horas antes de serem utilizados para diluição da vacina.","24 horas antes de serem utilizados para diluição da vacina"],"gabarito":"E"},{"n":54,"disciplina":"Enfermagem","tema":"Administração de Medicamentos e Cálculos","enunciado":"Acerca da administração de medicamentos pela via parenteral, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A técnica Z-tracking (trajeto em Z) não é recomendada na via intramuscular, pois aumenta o risco de irritação local e lesão. ( ) A hipodermóclise é contraindicada em situações de emergência e em indivíduos com desidratação severa. ( ) A infusão endovenosa lenta é aquela que dura de 30 a 60 minutos. As afirmativas são, respectivamente,","alternativas":["V – F – F.","F – F – F.","V – V – V.","F – V – V.","V – F – V"],"gabarito":"D"},{"n":55,"disciplina":"Enfermagem","tema":"Saúde Mental","enunciado":"Com base nos sinais e sintomas relacionados aos distúrbios psicológicos, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Alterações persistentes no sono, apetite, humor e rendimento funcional podem indicar distúrbios psicológicos e devem ser investigadas. ( ) Tristeza passageira por um evento específico é um sinal claro de transtorno depressivo maior. ( ) Ansiedade só é considerada um transtorno quando acompanhada de sintomas físicos como taquicardia ou sudorese. As afirmativas são, respectivamente,","alternativas":["V – F – V.","F – F – F.","V – F – F.","F – V – F.","V – V – V"],"gabarito":"C"},{"n":56,"disciplina":"Legislação do SUS","tema":"Lei 8.080/1990 - Organização e Competências","enunciado":"Uma atribuição da direção municipal do SUS é","alternativas":["formular políticas de alimentação e nutrição.","avaliar as redes hierarquizadas do SUS.","reformular políticas de nutrição e de saúde no âmbito empresarial.","coordenar serviço de vigilância sanitária.","executar serviços de saúde do trabalhador"],"gabarito":"E"},{"n":57,"disciplina":"Legislação do SUS","tema":"Lei 8.080/1990 - Princípios e Diretrizes","enunciado":"Em abril de 2025, a Lei nº 8.080/1990 foi alterada para inclusão de um novo princípio no âmbito do Sistema Único de Saúde. Assinale a opção que apresenta esse princípio.","alternativas":["Atenção humanizada.","Direito à informação.","Divulgação de informações.","Proteção integral dos direitos humanos.","Proteção a mulheres vítimas de violência."],"gabarito":"A"},{"n":58,"disciplina":"Legislação do SUS","tema":"Lei 8.142/1990","enunciado":"Com base na Lei nº 8.142/1990, uma das funções dos Conselhos de Saúde é","alternativas":["avaliar a situação de saúde.","implementar regiões de saúde.","controlar a execução das políticas de saúde.","promover a descentralização político-administrativa.","propor as diretrizes para a formulação da política de saúde"],"gabarito":"C"},{"n":59,"disciplina":"Enfermagem","tema":"Política Nacional de Humanização","enunciado":"A ideia de que a Política Nacional de Humanização (PNH) deve se fazer presente e estar inserida em todas as políticas e programas do SUS, diz respeito ao seguinte princípio dessa política:","alternativas":["cogestão.","acolhimento.","transversalidade.","defesa do direito dos usuários.","indissociabilidade entre atenção e gestão"],"gabarito":"C"},{"n":60,"disciplina":"Enfermagem","tema":"Controle de Infecção e Biossegurança","enunciado":"Com base nas normas e protocolos acerca do uso de Equipamentos de Proteção Individual (EPIs) e Equipamentos de Proteção Coletiva (EPCs), avalie as afirmativas a seguir e ass inale (V) para a verdadeira e (F) para a falsa. ( ) O uso de EPI substitui a necessidade de medidas de proteção coletiva em ambientes com risco biológico. ( ) Os equipamentos de proteção coletiva são indicados apenas para situações de emergência e não fazem parte das rotinas diárias de biossegurança. ( ) O empregador deve fornecer ao empregado, gratuitamente, EPI adequado ao risco e substituí -lo imediatamente, quando danificado ou extraviado. As afirmativas são, respectivamente,","alternativas":["V – V – F.","F – F – V.","V – V – V.","F – V – F.","V – F – V."],"gabarito":"B"}]},{"codigo":"sjc-analista-2025","ano":2025,"cargo":"Analista em Saúde — Enfermagem","orgao":"Prefeitura de São José dos Campos","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/analista-em-saude-enfermagemcns201-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/gabarito-definitovo-prefeitura-de-sjc.pdf","itens":[{"n":1,"disciplina":"Língua Portuguesa","tema":"Interpretação de Textos","enunciado":"Observe o trecho abaixo: Os excessos de nossa mocidade são saques sobre a nossa velhice, pagáveis com juros trinta anos depois. Sobre a significação desse segmento, é correto afirmar que","alternativas":["a expressão “trinta anos depois” equivale a “idade adulta”.","os excessos da mocidade trazem prejuízos na velhice.","a velhice repete os erros da mocidade.","a linguagem do texto é do campo semântico da Justiça.","os “saques” representam ações impensadas"],"gabarito":"B"},{"n":2,"disciplina":"Língua Portuguesa","tema":"Interpretação de Textos","enunciado":"Leia o texto abaixo. Nenhum outro povo do mundo, a não ser o brasileiro ou o português, poderia hoje, na verdade, com o orgulho que lhes conferem a sinceridade e a grandeza cristã da fraternidade que não desdenha a casta, a raça ou a cor, criar poemas com o este de Jorge Amado, “Gabriela, Cravo e Canela”. Assinale a afirmativa correta sobre sua significação ou estruturação.","alternativas":["Ao dizer “poemas” em relação ao romance de Jorge Amado, o enunciador do texto revela má informação.","“o brasileiro” e “o português” são agrupados, nesse caso, em função da língua comum que possuem e na qual se escreveu o romance citado.","“brasileiro” e “português” são substantivos que se transformaram em adjetivos, como mostra o texto.","A qualidade de brasileiros e por tugueses, destacada no texto, é a falta de preconceitos.","O emprego do demonstrativo “este” indica que o romance citado vai ser publicado em pouco tempo"],"gabarito":"D"},{"n":3,"disciplina":"Língua Portuguesa","tema":"Interpretação de Textos","enunciado":"Observe o seguinte texto de Rui Barbosa: Cada jornalista é, para o comum do povo, ao mesmo tempo um mestre de primeiras letras e um catedrático da democracia em ação, um advogado e um censor, um familiar e um magistrado. Bebidas com o primeiro pão do dia, as suas lições penetram até ao fundo das consciências inexpertas, onde vão elaborar a moral usual, os sentimentos e os impulsos, de que depende a sorte dos governos e das nações. Sobre esse segmento textual, assinale a afirmativa correta sobre sua significação e estruturação.","alternativas":["Segundo o texto, os jornalistas atuam profundamente sobre todas as camadas da população.","Os artigos dos jornais são chamados de “lições” porque pretendem ensinar de forma agressiva a todos os que desconhecem algo.","Como é referido no texto, os jornais têm interesses políticos, seus artigos moldam a visão de mundo dos leitores.","Rui Barbosa segue o lugar-comum de que os jornais eram lidos quando se tomava o café da manhã.","As “consciências inexpertas” são aquelas que se negam a aprender com os jornais"],"gabarito":"D"},{"n":4,"disciplina":"Língua Portuguesa","tema":"Interpretação de Textos","enunciado":"Leia com atenção o texto abaixo. Ensinam-se as fábulas de La Fontaine a todas as crianças, e não há uma só que as entenda. E, se as entendessem, seria ainda pior: pois a sua moral é tão embaralhada e tão inadequada à idade infantil que levaria as crianças ao vício antes que à virtude. Sobre sua estruturação ou significação, assinale a afirmativa correta.","alternativas":["As formas “ensinam -se” e “se as entendessem” são formas verbais na voz passiva pronominal (com o pronome SE).","A última oração do texto é classificada como adjetiva.","As duas ocorrências do pronome “as” se referem ao mesmo termo anterior.","As fábulas de La Fontaine levariam as crianças primeiramente ao vício e depois à virtude.","Após o uso de dois pontos (:) há uma retificação de algo dito anteriormente"],"gabarito":"C"},{"n":5,"disciplina":"Língua Portuguesa","tema":"Regência Verbal e Nominal","enunciado":"Em relação ao uso de pronomes relativos, assinale a frase que está inteiramente correta.","alternativas":["Picasso, muitos quadros do qual estão expostos no museu de São Paulo, foi um gênio da pintura no século passado.","Uma canção popular começa com esta frase: “Há amores que sua fama continua viva”.","O cantor declarou que o momento que conheceu sua atual mulher soube que ela era a mulher da sua vida.","Foi o clube quem decidiu rescindir o contrato do jogador.","Os países cuj as bandeiras mostram uma estrela estão bem desenvolvidos economicamente"],"gabarito":"E"},{"n":9,"disciplina":"Língua Portuguesa","tema":"Tempos, Modos e Vozes Verbais","enunciado":"Assinale a frase em que houve a passagem correta da voz passiva pronominal para a voz passiva com auxiliar.","alternativas":["A revolução é uma tentativa para que os sonhos se realizem / fossem realizados.","Não é possível depositar-se confiança em uma potência excessivamente grande / ser depositada.","É preciso combater -se a opinião alheia com nossas próprias armas / que seja combatida.","Uma guerra jamais deixa uma boa memória no lugar em que se travava / é travada.","Quando se fizer o depósito, a aposta valerá / ser feito"],"gabarito":"B"},{"n":10,"disciplina":"Língua Portuguesa","tema":"Ortografia e Acentuação","enunciado":"Entre as frases a seguir, assinale aquela que mostra uma grafia correta no que diz respeito às letras G ou J.","alternativas":["A arte é uma viajem sem volta.","Quanto mais observo o estranjeiro, mais amo a minha pátria.","Não viagem para Miami, porque as praias estão poluídas.","Ninguém que é honesto aceita priviléjios.","O amigo sempre lhe serviu de pajem"],"gabarito":"E"},{"n":11,"disciplina":"Língua Portuguesa","tema":"Estrutura e Formação de Palavras","enunciado":"Todas as frases abaixo foram formadas com o sufixo aumentativo -ão. Assinale a frase em que esse sufixo deixou de mostrar valor aumentativo, criando uma palavra nova.","alternativas":["O bairro nobre da cidade mostrava vários casarões.","O ator fez papel de bobalhão na frente de todos.","O novo herói da novela era um rapagão simpático.","Recebeu um abração do pai no aeroporto.","Musical é uma revista de mulheres nuas, dizendo palavrões, com a plateia gargalhando, e a censura encolhida"],"gabarito":"E"},{"n":13,"disciplina":"Língua Portuguesa","tema":"Coesão e Coerência","enunciado":"Nas frases abaixo há a presença do pronome “o”, relacionado a um termo anterior. Assinale a frase em que esse termo anterior inclui uma oração.","alternativas":["O pouco que sei devo-o à minha ignorância.","Não brigue com o problema. Resolva-o.","Vejo o bem e o aprovo, mas sigo o mal.","O dicionário é o pai dos inteligentes; os burros o dispensam.","É falta de educação calar um idiota, e crueldade o deixar prosseguir"],"gabarito":"A"},{"n":14,"disciplina":"Língua Portuguesa","tema":"Concordância Verbal e Nominal","enunciado":"As opções abaixo mostram frases com o pronome SE no singular; colocada no plural, a frase correta é:","alternativas":["Fez-se o exercício rapidamente / fez -se os exercícios rapidamente.","Precisa-se de um ajudante / precisam-se de ajudantes.","Gosta-se de doce / gosta-se de doces.","Aprecia-se um bom passeio / aprecia-se bons passeios.","Visitou-se o museu / visitou-se os museus"],"gabarito":"C"},{"n":16,"disciplina":"Raciocínio Lógico e Matemática","tema":"Razão, Proporção e Porcentagem","enunciado":"Um reservatório tem água até 1/3 da sua capacidade. Colocam-se no reservatório 5 galões de água, de modo que o reservatório agora está cheio até a metade. A capacidade volumétrica do reservatório medida em galões é igual a","alternativas":["15.","20.","25.","30.","45"],"gabarito":"D"},{"n":17,"disciplina":"Raciocínio Lógico e Matemática","tema":"Sequências e Padrões","enunciado":"Considere a sequência de letras PRESJCJSERPPRESJCJSERPPRESJCJSERP... formada pela repetição ilimitada da sequência PRESJCJSERP. A 2025ª letra dessa sequência é:","alternativas":["P.","R.","S.","J.","C"],"gabarito":"A"},{"n":18,"disciplina":"Raciocínio Lógico e Matemática","tema":"Geometria Plana","enunciado":"As medidas em centímetros dos lados de um triângulo são, respectivamente, a = 7,5, b = 11 e c = x, onde x é um número inteiro. O número de valores possíveis para x é igual a","alternativas":["11.","12.","13.","14.","15"],"gabarito":"E"},{"n":19,"disciplina":"Raciocínio Lógico e Matemática","tema":"Equações e Sistemas","enunciado":"A distância entre a 4ª saída e a 11ª saída de uma autoestrada é 98 km. A distância entre duas saídas consecutivas quaisquer é, no mínimo, de 10 km. A maior distância possível, em km, entre duas saídas consecutivas, da 4ª até a 11ª saídas, é igual a","alternativas":["14.","24.","28.","38.","40"],"gabarito":"D"},{"n":20,"disciplina":"Raciocínio Lógico e Matemática","tema":"Razão, Proporção e Porcentagem","enunciado":"Em um supermercado, havia um anúncio de uma promoção: “Somente hoje, 40% de desconto, pacote de meio quilo de tilápia por apenas R$ 7,20.” Sem o desconto, o preço do quilo da tilápia nesse supermercado era","alternativas":["R$ 10,08.","R$ 12,00.","R$ 14,40.","R$ 20,16.","R$ 24,00"],"gabarito":"E"},{"n":21,"disciplina":"Raciocínio Lógico e Matemática","tema":"Geometria Plana","enunciado":"Cada vértice de um quadrado ABCD está sobre um lado do quadrado EFGH. O vértice A está sobre o lado EF, de tal forma que EA = 4 e AF = 2. A razão entre a área do quadrado ABCD e a área do quadrado EFGH é igual a","alternativas":["5 9.","4 9.","1 3.","2 3.","1 2"],"gabarito":"A"},{"n":22,"disciplina":"Raciocínio Lógico e Matemática","tema":"Regra de Três e Problemas Aritméticos","enunciado":"Solange executou 3 tarefas em sequência e sem intervalos entre elas. As 3 tarefas consumiram exatamente o mesmo tempo cada uma. Solange começou a primeira tarefa às 13h20min e terminou a segunda tarefa às 16h12min. Solange terminou a terceira tarefa às","alternativas":["16h52min.","17h38min.","18h16min.","19h04min.","20h30min"],"gabarito":"B"},{"n":23,"disciplina":"Raciocínio Lógico e Matemática","tema":"Probabilidade","enunciado":"Um dado cúbico, com as faces numeradas de 1 a 6, é tal que quando lançado todas as faces têm a mesma probabilidade de ficar voltada para cima. Lança-se esse dado duas vezes em sequência. A probabilidade de que o produto dos dois números sorteados seja maior do que 8 é","alternativas":["9 18.","10 18.","11 18.","12 18.","13 18"],"gabarito":"B"},{"n":24,"disciplina":"Raciocínio Lógico e Matemática","tema":"Argumentação Lógica","enunciado":"Adriana pratica exatamente um esporte a cada dia da semana. Ela rema 3 dias na semana, mas nunca em dias consecutivos. Às quartas-feiras ela corre e dois dias depois ela faz stand-up. Adriana também nada e joga beach-tennis, mas ela nunca joga beach- tennis após nadar ou remar. O dia da semana no qual Adriana nada é","alternativas":["domingo.","segunda-feira.","terça-feira.","quinta-feira","sábado."],"gabarito":"B"},{"n":25,"disciplina":"Raciocínio Lógico e Matemática","tema":"Análise Combinatória","enunciado":"Em uma folha de papel há 16 pontos azuis e 4 pontos verdes. Cada par de pontos azuis será conectado por um segmento de reta azul. Os demais pares de pontos ((verde, verde) e (verde, azul)) serão conectados por segmentos de reta verdes. O número de segmentos de reta verdes será então igual a","alternativas":["54.","60.","64.","70.","84. Atualidades"],"gabarito":"D"},{"n":31,"disciplina":"Legislação do SUS","tema":"Lei 8.080/1990 - Organização e Competências","enunciado":"Acerca da organização, da direção e da gestão do SUS, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) As ações e serviços de saúde, executados pelo Sistema Único de Saúde (SUS), seja diretamente ou mediante participação complementar da iniciativa privada, serão organizados de forma regionalizada e hierarquizada em níveis de complexidade crescente. ( ) A direção do Sistema Único de Saúde (SUS) é única. ( ) Os municípios poderão constituir consórcios para desenvolver em conjunto as ações e os serviços de saúde que lhes correspondam. As afirmativas são, respectivamente,","alternativas":["V – V – V.","V – F – F.","F – V – V.","F – F – V.","V – F – V"],"gabarito":"A"},{"n":32,"disciplina":"Legislação do SUS","tema":"Lei 8.080/1990 - Financiamento","enunciado":"Acerca da gestão financeira do SUS, conforme estabelece a Lei 8.080/1990, avalie as afirmativas a seguir. I. Os recursos financeiros do Sistema Único de Saúde (SUS) serão depositados em conta especial, em cada esfera de sua atuação, e movimentados sob fiscalização dos respectivos Conselhos de Saúde. II. Na esfera federal, os recursos financeiros, originários do Orçamento da Seguridade Social, de outros Orçamentos da União, além de outras fontes, serão administrados pelo Ministério da Saúde, por meio do Fundo Nacional de Saúde. III. O Ministério da Saúde acompanhará, através de seu sistema de auditoria, a conformidade à programação aprovada da aplicação dos recursos repassados a Estados e Municípios. Constatada a malversação, d esvio ou não aplicação dos recursos, caberá ao Ministério da Saúde aplicar as medidas previstas em lei. IV. Fica vedada às autoridades responsáveis pela distribuição da receita efetivamente arrecadada a transferência automática ao Fundo Nacional de Saúde (FNS). Está correto o que se afirma em","alternativas":["I e II, apenas.","III e IV, apenas.","I, II e III, apenas.","II, III e IV, apenas.","I, II, III e IV."],"gabarito":"C"},{"n":33,"disciplina":"Legislação do SUS","tema":"Planejamento em Saúde","enunciado":"Acerca do planejamento e do orçamento do SUS, as afirmativas a seguir estão corretas, à exceção de uma. Assinale-a.","alternativas":["O processo de planejamento e orçamento do Sistema Único de Saúde (SUS) será ascendente, do nível local até o federal, ouvidos seus órgãos deliberativos, compatibilizando -se as necessidades da política de saúde com a disponibilidade de recursos em planos de saúde dos Municípios, dos Estados, do Distrito Federal e da União.","Os planos de saúde serão a base das atividades e programações de cada nível de direção do Sistema Único de Saúde (SUS), e seu financiamento será previsto na respectiva proposta orçamentária.","É vedada a transferência de recursos para o financiamento de ações não previstas nos planos de saúde, exceto em situações emergenciais ou de calamidade pública, na área de saúde.","O Ministério da Saúde estabelecerá as diretrizes a serem observadas na elaboração dos planos de saúde, em função das características epidemiológicas e da organização dos serviços em cada jurisdição administrativa.","Não será permitida a destinação de subvenções e auxílios a instituições prestadoras de serviços de saúde com finalidade lucrativa"],"gabarito":"D"},{"n":34,"disciplina":"Enfermagem","tema":"Política Nacional de Humanização","enunciado":"A Política Nacional de Humanização (PNH), também conhecida como HumanizaSUS, é uma política pública do Sistema Único de Saúde (SUS) que visa transformar as práticas de a tenção e gestão na saúde, alicerçada nos seguintes princípios:","alternativas":["dissociação entre a atenção e a gestão dos processos de produção de saúde, segmentação e subordinação dos atores à direção única.","inseparabilidade entre a atenção e a gestão dos processos de produção de saúde, transversalidade e autonomia e protagonismo dos sujeitos.","dissociação entre a atenção e a gestão dos processos de produção de saúde, segmentação e autonomia e protagonismo dos sujeitos.","inseparabilidade entre a atenção e a gestão dos processos de produção de saúde, capilaridade estrutural e subordinação hierárquica.","gestão independente da atenção, ações dissociativas e subordinação estrutural"],"gabarito":"B"},{"n":35,"disciplina":"Legislação do SUS","tema":"Lei 8.142/1990","enunciado":"A Lei nº 8.142/1990 dispõe sobre a participação da comunidade na gestão do Sistema Único de Saúde (SUS) e sobre as transferências intergovernamentais de recursos financeiros na área da saúde e dá outras providências. Avalie, com base nessa lei, se os recursos do Fundo Nacional de Saúde (FNS) serão alocados como: I. despesas de custeio e de capital do Ministério da Saúde, seus órgãos e entidades, da administração direta e indireta. II. investimentos previstos em lei orçamentária, de iniciativa do Poder Legislativo e aprovados pelo Congresso Nacional. III. investimentos previstos no Plano Quinquenal do Ministério da Saúde. IV. cobertura das ações e serviços de saúde a serem implementados pelos Municípios, Estados e Distrito Federal. Estão corretos os itens","alternativas":["I e II, apenas.","III e IV, apenas.","I, II e III, apenas.","II, III e IV, apenas.","I, II, III e IV"],"gabarito":"E"},{"n":36,"disciplina":"Legislação do SUS","tema":"Direitos dos Usuários do SUS","enunciado":"A Resolução do Conselho Nacional de Saúde nº 553/2017 dispõe sobre a Carta dos Direitos e Deveres da Pessoa Usuária da Saúde. Ela aprova a atualização da Carta dos Direitos e Deveres da Pessoa Usuária da Saúde que dispõe sobre as diretrizes dos Direitos e Deveres da Pessoa Usuária da Saúde. Avalie se tais diretrizes incluem: I. Toda pessoa tem direito, em tempo hábil, ao acesso a bens e serviços ordenados e organizados para garantia da promoção, prevenção, proteção, tratamento e recuperação da saúde. II. Toda pessoa tem direito ao atendimento integral, aos procedimentos adequados e em tempo hábil a resolver o seu problema de saúde, de forma ética e humanizada. III. Toda pessoa tem direito ao atendimento inclusivo, humanizado e acolhedor, realizado por profissionais qualificados, em ambiente limpo, confortável e acessível. Está correto o que se afirma em","alternativas":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"gabarito":"E"},{"n":37,"disciplina":"Legislação do SUS","tema":"Constituição Federal - Saúde","enunciado":"De acordo com a Constituição Federal de 1988, no que se refere à Seguridade Social, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A saúde é direito de todos e dever d o Estado, garantido mediante políticas sociais e econômicas que visem à redução do risco de doença e de outros agravos e ao acesso universal e igualitário às ações e serviços para sua promoção, proteção e recuperação. ( ) São de relevância pública as açõ es e serviços de saúde, cabendo ao Poder Público dispor, nos termos da lei, sobre sua regulamentação, fiscalização e controle, devendo sua execução ser feita diretamente ou através de terceiros e, também, por pessoa física ou jurídica de direito privado. ( ) As ações e serviços públicos de saúde integram uma rede regionalizada e hierarquizada e constituem um sistema único. ( ) O sistema de saúde é organizado de acordo com as seguintes diretrizes: (i) centralização, com direção única em cada esfera de governo, (ii) atendimento parcial, com prioridade para as atividades assistenciais e (iii) participação da comunidade. As afirmativas são, respectivamente,","alternativas":["V – V – V – V.","V – V – F – F.","F – F – V – V.","V – V – V – F.","V – V – F – V"],"gabarito":"D"},{"n":38,"disciplina":"Enfermagem","tema":"Segurança do Paciente","enunciado":"A RDC nº 36, de 2013, institui ações para a segurança do paciente em serviços de saúde e dá outras providências. Com base na referida resolução, a aplicação sistêmica e contínua de políticas, procedimentos, condutas e recursos na identificação, análise, avaliação, comunicação e controle de riscos e eventos adversos que afetam a segurança, a saúde humana, a integridade profissional, o meio ambiente e a imagem institucional define:","alternativas":["gestão de risco.","segurança do paciente.","evento adverso.","incidente.","plano de segurança do paciente em serviços de saúde"],"gabarito":"A"},{"n":39,"disciplina":"Enfermagem","tema":"Segurança do Paciente","enunciado":"A RDC nº 63, de 25/11/2011, dispõe sobre os Requisitos de Boas Práticas de Funcionamento para os Serviços de Saúde. Com base nessa resolu ção, acerca das Boas Práticas de Funcionamento (BPF), avalie as afirmativas a seguir. I. As Boas Práticas de Funcionamento (BPF) são os componentes da Garantia da Qualidade que asseguram que os serviços são ofertados com padrões de qualidade adequados. II. As BPF são orientadas primeiramente à redução dos riscos inerentes à prestação de serviços de saúde. III. Os conceitos de Garantia da Qualidade e Boas Práticas de Funcionamento (BPF) estão inter-relacionados. IV. As BPF determinam que o serviço de saúde d eve ser capaz de ofertar serviços dentro dos padrões de qualidade exigidos, atendendo aos requisitos das legislações e regulamentos vigentes. Está correto o que se afirma em","alternativas":["I e II, apenas.","III e IV, apenas.","I, II e III, apenas.","II, III e IV, apenas.","I, II, III e IV"],"gabarito":"E"},{"n":40,"disciplina":"Enfermagem","tema":"Segurança do Paciente","enunciado":"A RDC nº 63, de 25/11/2011, que dispõe sobre os Requisitos de Boas Práticas de Funcionamento para os Serviços de Saúde, estabelece, em relação ao prontuário do paciente, as seguintes disposições, à exceção de uma. Assinale-a.","alternativas":["A responsabilidade pelo r egistro em prontuário cabe aos profissionais de saúde que prestam o atendimento.","A guarda do prontuário é de responsabilidade do serviço de saúde, devendo obedecer às normas vigentes.","O serviço de saúde deve manter os prontuários em local seguro, e m boas condições de conservação e organização, permitindo o seu acesso sempre que necessário.","O serviço de saúde deve garantir que o prontuário não contenha registros relativos à identificação e a procedimentos prestados ao paciente considerados sensíveis.","O serviço de saúde deve garantir que o prontuário seja preenchido de forma legível por todos os profissionais envolvidos diretamente na assistência ao paciente, com aposição de assinatura e carimbo em caso de prontuário em meio físico. Enfermagem"],"gabarito":"D"},{"n":41,"disciplina":"Enfermagem","tema":"Epidemiologia e Vigilância em Saúde","enunciado":"A estatística é uma ferramenta essencial na pesquisa em saúde, pois permite descrever dados e realizar inferências sobre populações a partir de amostras. Com base na aplicação da estatística em estudos epidemiológicos, é correto afirmar que","alternativas":["a estatística descritiva é usada apenas para testar hipóteses em pesquisas clínicas.","o valor p (p -valor) indica a magnitude do efeito observado entre duas variáveis.","a média é a única medida d e tendência central recomendada em distribuições assimétricas.","o desvio-padrão mede a dispersão ou variabilidade dos valores em um conjunto de dados em relação à média.","a variância é uma medida de tendência central que expressa o valor mais frequente nos dados"],"gabarito":"D"},{"n":42,"disciplina":"Enfermagem","tema":"Epidemiologia e Vigilância em Saúde","enunciado":"As medidas de frequência são fundamentais para descrever o comportamento das doenças em uma população. Com base na definição e aplicação dessas medidas, é correto afirmar que a incidência acumulada","alternativas":["mede o número total de casos, novos e antigos, em uma população, em um dado momento.","expressa a proporção de indivíduos inicialmente livres da doença que adoecem ao longo de um período definido.","é uma taxa que considera o tempo de seguimento individual de cada pessoa em risco.","representa o número de óbitos por uma determinada causa, dividido pela população total.","é uma medida transversal que não considera o fator tempo"],"gabarito":"B"},{"n":43,"disciplina":"Enfermagem","tema":"Controle de Infecção e Biossegurança","enunciado":"Em uma unidade hospitalar foi identificado o aumento de casos de infecção do trato urinário associada ao uso de cateter vesical. Avalie se as diretrizes do Ministério da Saúde para prevenir esse tipo de infecção incluem: I. Estabelecer protocolos para inserção asséptica e manutenção do cateter, com capacitação da equipe de saúde. II. Realizar cultura urinária semanal em todos os pacientes com cateter, independentemente de sintomas. III. Utilizar antibióticos profiláticos rotineiramente em todos os pacientes com cateter vesical. Está correto o que se apresenta em","alternativas":["I, apenas.","II e III, apenas.","I e III, apenas.","II, apenas.","I, II e III"],"gabarito":"A"},{"n":44,"disciplina":"Enfermagem","tema":"Prática Baseada em Evidências","enunciado":"A Estatística Analítica é uma área essencial para a tomada de decisões baseada em dados, sendo amplamente utilizada na investigação científica. Nesse sentid o, uma aplicação correta da Estatística Analítica no contexto da análise de dados é","alternativas":["utilizar médias aritméticas para descrever tendências em dados assimétricos, sem considerar outros indicadores.","estimar parâmetros populacionais a partir de amostra s por meio de intervalos de confiança e testes de hipóteses.","representar graficamente a distribuição dos dados como principal método para inferência estatística.","realizar testes estatísticos apenas quando toda a população tiver sido analisada, garantindo validade total dos resultados.","assumir que correlação entre duas variáveis implica uma relação de causa e efeito entre elas"],"gabarito":"B"},{"n":45,"disciplina":"Enfermagem","tema":"Ética e Legislação em Enfermagem","enunciado":"Acerca das disposições do Código de Ética dos Profissionais de Enfermagem, avalie as afir mativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) É vedado ao profissional de enfermagem o cumprimento de prescrição à distância, exceto em casos de urgência e emergência. ( ) O Código de Ética proíbe o profissional de enfermage m de executar procedimentos ou participar da assistência à saúde sem o consentimento formal da pessoa, independentemente do risco de morte. ( ) É um dever do profissional de enfermagem comunicar formalmente ao Conselho Regional de Enfermagem fatos que infrinjam dispositivos éticos-legais e que possam prejudicar o exercício profissional e a segurança à saúde do paciente. As afirmativas são, respectivamente,","alternativas":["V – F – F.","F – F – F.","V – F – V.","F – V – V.","V – V – V"],"gabarito":"C"},{"n":46,"disciplina":"Enfermagem","tema":"Fundamentos e Semiotécnica","enunciado":"Na assistência de enfermagem, é fundamental que os profissionais apliquem corretamente as técnicas básicas para garantir segurança e eficácia nos procedimentos. Acerca desses procedimentos, é correto afirmar que","alternativas":["a administração de medica mentos por via subcutânea exige sempre a aspiração do êmbolo antes da injeção.","na realização de curativos em feridas cirúrgicas limpas, deve - se iniciar a limpeza da região de fora para o centro da incisão, para evitar infecção.","a passagem da sonda nasogástrica deve ser feita com o paciente em posição supina, para evitar náuseas e aspiração.","o cateter vesical de demora deve ser introduzido até ocorrer saída de urina, e só então o balonete deve ser insuflado.","na oxigenoterapia com máscara de Venturi, a fração inspirada de oxigênio (FiO₂) é determinada pelo fluxo de oxigênio e pela profundidade da respiração do paciente."],"gabarito":"D"},{"n":47,"disciplina":"Enfermagem","tema":"Controle de Infecção e Biossegurança","enunciado":"As medidas de prevenção e controle de infecções são fundamentais para evitar a disseminação do coronavírus (SARS - CoV-2) e outros microrganismos patogênicos. Acerca dessas medidas, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Atualmente as precauções para contato são suficientes para prevenir a contaminação e disseminação da COVID-19. ( ) As precauções relativas a aerossóis são indicadas para evitar a transmissão de partículas menores ou iguais a 5 , que permanecem em suspensão no ar, podendo ser transportadas por longas distâncias. ( ) Nos casos de infecção por meningite bacteriana e rubéola o paciente pode ser internado com outros infectados pelo mesmo microrganismo, desde que respeitada a distância mínima de um metro entre os leitos. As afirmativas são, respectivamente,","alternativas":["F – V – V.","V – F – V.","F – F – F.","V – V – V.","F – V – F"],"gabarito":"A"},{"n":48,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"No atendimento a um paciente adulto em parada cardiorrespiratória (PCR) com ritmo não chocável , a epinefrina deve ser administrada o mais precocemente possível, idealmente em até","alternativas":["2 minutos depois do início da PCR.","5 minutos depois do início da PCR.","7 minutos depois do início da PCR.","10 minutos depois do início da PCR.","12 minutos depois do início da PCR"],"gabarito":"B"},{"n":49,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"No atendimento a emergências pediátricas, é importante que o profissional de saúde seja capaz de identificar os sinais e sintomas comuns de AVC, que podem ser gerais ou focais, em crianças. Com base nas diretrize s atualizadas, da American Heart Association, assinale a opção que apresenta respectivamente um sinal ou sintoma focal e um geral.","alternativas":["Confusão mental e febre.","Náusea e paralisia facial.","Vômito e distúrbio visual.","Convulsão e dor de cabeça.","Distúrbio da fala e ataxia"],"gabarito":"E"},{"n":50,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"Um paciente adulto apresenta dor torácica que ocorre apenas com esforços físicos prolongados e intensos. Com essas características, a dor apresentada pelo paciente é classificada como angina","alternativas":["Classe I.","Classe II.","Classe III.","Classe IV.","Classe V"],"gabarito":"A"},{"n":51,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"O indicador de saúde Taxa de Mortalidade Infantil diz respeito ao número de óbitos de menores de","alternativas":["1 ano de idade.","2 anos de idade.","5 anos de idade.","7 anos de idade.","10 anos de idade"],"gabarito":"A"},{"n":52,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"Em pacientes com pulso paradoxal, a pressão arterial sistólica e a pressão de pulso caem drasticamente durante a inspiração. No caso da pressão arterial sistólica há uma queda superior a","alternativas":["2 mmHg.","4 mmHg.","5 mmHg.","8 mmHg.","10 mmHg"],"gabarito":"E"},{"n":53,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"Um paciente adulto, com suspeita de pancreatite aguda, apresenta, entre outros sinais e sintomas, sinal de Grey-Turner. Esse sinal é caracterizado pela presença de","alternativas":["equimose nos flancos.","equimose periumbilical.","timpanismo no hipocôndrio direito.","dor à percussão do hipocôndrio direito.","dor à descompressão do ponto de McBurney"],"gabarito":"A"},{"n":54,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"Com base nas diretrizes e protocolos do Ministério da Saúde acerca do parto normal, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Recomenda-se a administração de um enema no momento da admissão para o parto. ( ) Deve-se auscultar a frequência cardíaca fetal, ao menos durante 1 minuto, durante e após uma contração. ( ) Recomenda-se o cuidado d a parturiente em maternidade baseada em hospital, com presença de médico obstetra em caso de apresentação cefálica alta ou móvel em nulípara. As afirmativas são, respectivamente,","alternativas":["V – F – V.","F – V – V.","V – V – V.","F – F – F.","V – F – F"],"gabarito":"B"},{"n":55,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"De acordo com as disposições do Ministério da Saúde, um dos critérios para inclusão de gestantes no Protocolo Clínico e Diretrizes Terapêuticas (PCDT) da Anemia por Deficiência de Ferro é","alternativas":["Hb abaixo de 11 g/dL.","Hb abaixo de 15 g/dL.","Hb abaixo de 20 g/dL.","Ferritina abaixo de 40 ng/mL.","Ferritina abaixo de 50 ng/mL."],"gabarito":"A"},{"n":56,"disciplina":"Enfermagem","tema":"Arboviroses (Dengue, Zika, Chikungunya, Febre Amarela, Oropouche e Nilo Ocidental)","enunciado":"Criança de 10 anos, pesando 28 quilos, apresenta suspeita de dengue sem sinais de alarme, sem condição especial, risco social ou comorbidades. O volume diário recomendado para hidratação oral dessa criança é de","alternativas":["50 mL/kg/dia.","80 mL/kg/dia.","100 mL/kg/dia.","120 mL/kg/dia.","130 mL/kg/dia"],"gabarito":"B"},{"n":58,"disciplina":"Enfermagem","tema":"Hanseníase","enunciado":"Um paciente foi diagnosticado com Hanseníase Paucibacilar (PB). Essa Hanseníase é caracterizada pela presença de","alternativas":["mais de cinco lesões cutâneas e baciloscopia obrigatoriamente negativa.","uma a três lesões cutâneas e baciloscopia obrigatoriamente positiva.","mais de cinco lesões cutâneas e baciloscopia obrigatoriamente positiva.","uma a cinco lesões cutâneas e baciloscopia obrigatoriamente negativa.","três a seis lesões cutâneas e baciloscopia obrigatoriamente positiva"],"gabarito":"D"},{"n":59,"disciplina":"Enfermagem","tema":"Diabetes Mellitus","enunciado":"De acordo com a Sociedade Brasileira de Diabetes, os sinais e sintomas de diabetes podem ser classificados como típicos e sugestivos. Entre os sinais sugestivos de hiperglicemia está a","alternativas":["polifagia.","polidipsia.","noctúria.","desidratação.","perda de peso"],"gabarito":"C"},{"n":60,"disciplina":"Enfermagem","tema":"Tuberculose","enunciado":"Acerca da baciloscopia de escarro para a detecção da tuberculose pulmonar em adultos, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa ( ) É um método indicado para o sintomático respiratório, durante estratégia de busca ativa. ( ) A baciloscop ia de escarro deve ser realizada em duas amostras. ( ) Em crianças, a sensibilidade da baciloscopia é bastante diminuída pela dificuldade de obtenção de uma amostra com boa qualidade. As afirmativas são, respectivamente,","alternativas":["F – V – F.","V – V – V.","F – F – F.","V – F – V.","F – F – V"],"gabarito":"B"},{"n":61,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"Com base nos protocolos do Ministério da Saúde acerca da assistência ao recém -nascido com suspeita de microcefalia relacionada à infecção pelo zika vírus, avalie as afirmativas a seguir. I. A microcefalia é caracterizada por perímetro cefálico abaixo de 35 cm para ambos os sexos, segundo as curvas da OMS. II. Considerando-se que a maioria dos RN de parto normal apresenta suturas cavalgadas, orienta -se que a medição do perímetro cefálico seja refeita com 24 h a 48 h de vida. III. A aferição do perímetro cefálico deve ser realizada com fita métrica inextensível, posicionada logo acima das sobrancelhas e na parte mais proeminente do osso occipital. Está correto o que se afirma em","alternativas":["I, II e III.","I, apenas.","II, apenas.","I e II, apenas.","II e III, apenas"],"gabarito":"E"},{"n":62,"disciplina":"Enfermagem","tema":"Hipertensão Arterial","enunciado":"De acordo com as diretrizes da Sociedade Brasileira de Hipertensão, entre os parâmetros que classificam um paciente com Hipertensão Arterial Estágio 2 está","alternativas":["PAD ≥ 85 mmHg.","PAS ≥ 130 mmHg.","PAD entre 90 e 99 mmHg.","PAS entre 140 e 159 mmHg.","PAD entre 100 e 109 mmHg"],"gabarito":"E"},{"n":63,"disciplina":"Enfermagem","tema":"Processo de Enfermagem e SAE","enunciado":"De acordo com as disposições do COFEN, quando o profissional de enfermagem realiza as intervenções, ações e atividades previstas no planejamento assistencial, ele está atuando de acordo com a seguinte etapa do Processo de Enfermagem:","alternativas":["Evolução.","Avaliação.","Diagnóstico.","Implementação.","Planejamento."],"gabarito":"D"},{"n":64,"disciplina":"Enfermagem","tema":"Gerenciamento de Resíduos de Serviços de Saúde (GRSS)","enunciado":"De acordo com as normas do Ministério da Saúde, acerca do descarte de bolsas de sangue e hemocomponentes rejeitados por contaminação ou por má conservação, é correto afirmar que as bolsas","alternativas":["devem ser submetidas a tratamento ou dispostas em aterro de resíduos perigosos.","devem ser tratadas antes da disposição final ambientalmente adequada.","devem atender às regras de manejo dos resíduos perfurocortantes.","podem ser submetidas a processo de recuperação ou reutilização.","devem ser descartadas como rejeitos e não precisam de tratamento prévio à sua destinação"],"gabarito":"B"},{"n":65,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"Entre as ações estratégicas do Ministério da Saúde para o enfrentamento das doenças crônicas não transmissíveis está","alternativas":["a redução da prevalência do tabagismo.","o aumento da cobertura vacinal de idosos contra a influenza.","a diminuição das mortes por dengue, zika e chikungunya.","o aumento da notificação compulsória de tuberculose.","a redução no índice de transtorno mental incapacitante"],"gabarito":"A"},{"n":66,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"O câncer de intestino é o tumor com maior projeção para o quinquênio 2026-2030, com aumento p revisto em 10% entre as pessoas de 30 a 69 anos. De acordo com as orientações do Ministério da Saúde, o rastreamento para esse tipo de câncer deve ser realizado em pessoas pertencentes aos grupos de médio e alto risco. Nesse sentido, assinale a opção que apresenta um fator de médio risco.","alternativas":["Sexo masculino.","Idade ≥ 50 anos.","Síndrome de Lynch.","Histórico familiar de câncer de intestino.","Histórico de doença inflamatória do intestino"],"gabarito":"B"},{"n":67,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"Com base nas disposições do Ministério da Saúde acerca da Síndrome da Rubéola Congênita (SRC), avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Todo recém-nascido cuja mãe foi contato de caso suspeito ou confirmado de rubéola durante a gestação, é considerado um caso suspeito de SRC. ( ) Todos os casos suspeitos ou confirmados de SRC são de notificação compulsória imediata. ( ) A transmissão vertical ocorre exclusivamente no momento do parto ou durante a amamentação, não sendo possível a infecção fetal transplacentária. As afirmativas são, respectivamente,","alternativas":["V – F – V.","F – F – F.","V – V – F.","F – V – F.","V – V – V"],"gabarito":"C"},{"n":68,"disciplina":"Enfermagem","tema":"Centro Cirúrgico","enunciado":"Com base no protocolo de Cirurgia Segura do Ministério da Saúde, assinale a afirmativa correta.","alternativas":["Somente o cirurgião ou o anestesista podem fazer checagens relacionadas aos exames de imagens e laboratoriais.","O time out é a etapa que ocorre antes da saída do paciente da sala de cirurgia.","A demarcação do sítio cirúrgico deve ser rea lizada imediatamente antes da indução anestésica.","A profilaxia antimicrobiana deve ser realizada uma hora antes da incisão cirúrgica.","A checagem quanto à reserva de hemocomponentes deve ser realizada antes da incisão cirúrgica"],"gabarito":"D"},{"n":69,"disciplina":"Enfermagem","tema":"Imunização","enunciado":"Um trabalhador da saúde, 30 anos de idade, foi ao posto de saúde para atualizar as vacinas recomendadas em razão da sua profissão. Em relação à tríplice viral constava que ele já havia tomado 2 doses da vacina. Nesse caso, é correto afirmar que","alternativas":["ele deve tomar uma dose de reforço.","ele deve completar o esquema com uma dose e, após 12 meses tomar uma dose de reforço.","o esquema vacinal está completo, não necessitando de doses de reforço.","para completar o esquema básico ele deverá tomar mais duas doses da vacina com intervalo mínimo de 60 dias entre as doses e uma dose de reforço após 6 meses da última dose.","para completar o esquema básico ele deverá tomar mais duas doses da vacina com intervalo mínimo de 60 dias entre as doses, sem necessidade de dose de reforço"],"gabarito":"C"},{"n":70,"disciplina":"Enfermagem","tema":"Imunização","enunciado":"Em relação à vacina da COVID -19, o Ministério da Saúde recomenda, independentemente da quantidade de doses prévias recebidas, duas doses anuais com intervalo de 6 meses para o grupo de","alternativas":["gestantes.","crianças indígenas.","populações ribeirinhas.","crianças com comorbidades.","idosos a partir de 60 anos de idade."],"gabarito":"E"}]},{"codigo":"fhemig-tecnico-2023","ano":2023,"cargo":"Técnico de Enfermagem — 30h, Nível II","orgao":"Fundação Hospitalar do Estado de Minas Gerais — FHEMIG","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/profissional-de-enfermagem-penf-tecnico-de-enfermagem-30h-nivel-iicnm101-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/gabarito-definitivo-fhemig-retificado-01.11.2023.pdf","itens":[{"n":6,"disciplina":"Língua Portuguesa","tema":"Estrutura e Formação de Palavras","enunciado":"O sufixo -tério também pode apresentar o valor de “lugar”. Assinale a opção em que o vocábulo destacado, formado com o sufixo -tério, tem seu significado corretamente indicado.","alternativas":["batistério – local de cultos batistas.","deletério – lugar de dor.","necrotério – lugar de autópsias.","biotério – lugar de moradia de biólogos.","monastério – lugar de monges"],"gabarito":"E"},{"n":7,"disciplina":"Língua Portuguesa","tema":"Semântica e Significação","enunciado":"Assinale a opção em que o segmento formado pelo verbo ter + substantivo foi substituído por um só verbo de sentido equivalente.","alternativas":["Algumas das mais belas árvores genealógicas que vicejam por aí têm raízes no esterco / se erradicam.","Todas as famílias felizes têm semelhanças: cada família Infeliz é infeliz à sua maneira / se assimilam.","Famílias com bebê e famílias sem bebê têm dó umas das outras / se apenalizam.","Muitos cariocas só têm prazer no Carnaval / se aprazem.","Muitos médicos não têm tempo para o lazer / se voltam."],"gabarito":"D"},{"n":8,"disciplina":"Língua Portuguesa","tema":"Coesão e Coerência","enunciado":"As preposições têm dois valores básicos: podem ter valor gramatical, quando são exigidas por um termo anterior, com presença obrigatória, e valor nocional quando são empregadas para acrescentar alguma informação ao texto. Assinale a opção em que a preposição de mostra valor nocional.","alternativas":["O primeiro passo para conhecer-se é desconfiar de si mesmo.","O jovem não precisa de razões para viver.","As crianças necessitam mais de modelos que de críticos.","Um cão velho já não deve latir, pois já não é capaz de morder.","O maior homem do mundo é aquele que não perde seu coração de criança"],"gabarito":"E"},{"n":9,"disciplina":"Língua Portuguesa","tema":"Regência Verbal e Nominal","enunciado":"Assinale a opção em que a conjunção e mostra valor de consequência.","alternativas":["A liberdade não é nada senão a distância entre a caça e o caçador.","Nós todos apoiamos a liberdade, mas usamos a mesma palavra e não queremos dizer todos a mesma coisa.","A liberdade leva ao humor e o humor conduz à liberdade.","Ria e o mundo rirá com você.","O sorriso custa menos que a eletricidade e dá mais luz"],"gabarito":"D"},{"n":11,"disciplina":"Raciocínio Lógico e Matemática","tema":"Conjuntos","enunciado":"Uma casa tem, ao todo, 7 portas. Se é verdade que pelo menos 3 portas não estão abertas, pode-se concluir que, nessa casa","alternativas":["a maioria das portas está fechada.","a maioria das portas está aberta.","há, no mínimo, 4 portas fechadas.","há, no mínimo, 3 portas fechadas.","há, no máximo, 3 portas fechadas"],"gabarito":"D"},{"n":12,"disciplina":"Raciocínio Lógico e Matemática","tema":"Conjuntos","enunciado":"Considere dois conjuntos finitos A e B tais que A  B tem exatos 9 elementos e A  B tem exatos 2 elementos. Se A tem um elemento a mais que B, então o conjunto B possui","alternativas":["6 elementos.","5 elementos.","4 elementos.","3 elementos.","2 elementos"],"gabarito":"B"},{"n":13,"disciplina":"Raciocínio Lógico e Matemática","tema":"Regra de Três e Problemas Aritméticos","enunciado":"João está parado em certo degrau de uma escada. Se ele descer do degrau em que está até a base e, em seguida, subir até o último degrau, ele contará 23 degraus. Se, ao contrário, ele subir do lugar em que está até o topo e, em seguida, descer até a base, contará 28 degraus. Assinale a opção que indica o número de degraus dessa escada.","alternativas":["17.","18.","19.","20.","21"],"gabarito":"A"},{"n":15,"disciplina":"Raciocínio Lógico e Matemática","tema":"Argumentação Lógica","enunciado":"Três amigos têm idades diferentes. Daqui a 4 anos, o mais novo terá a idade que o mais velho tem hoje. Há 3 anos, o mais velho tinha a idade que o amigo com idade intermediária tem hoje. No ano que vem, a soma das idades será 41. Há um ano, a idade do mais velho era um múltiplo de","alternativas":["3.","5.","7.","8.","9. Informática Básica"],"gabarito":"C"},{"n":16,"disciplina":"Informática","tema":"Segurança da Informação","enunciado":"No contexto da segurança de computadores e sistemas conectados na Internet, uma estratégia comumente usada por invasores é o envio de arquivos que, quando abertos, podem desencadear procedimentos nocivos no equipamento hospedeiro. Assinale a opção que indica a extensão que caracteriza um tipo de arquivo potencialmente perigoso usado nesse tipo de invasão.","alternativas":[".csv",".exe",".jpeg",".pdf",".txt"],"gabarito":"B"},{"n":17,"disciplina":"Informática","tema":"Microsoft Word","enunciado":"João preparou um documento no Word contendo referências às atividades de alguns setores da sua organização, mas antes de entregar o texto final solicitou a dois de seus colegas, X e Y, que fizessem uma revisão do texto e corrigissem os trechos que apresentavam falhas e/ou incorreções. Para isso, João enviou o documento Word para X, e depois de recebê -lo de volta, fez o mesmo para Y. Assinale a opção que apresenta o recurso do Word que João utilizou para identificar e analisar as cont ribuições de cada revisor.","alternativas":["Controlar Alterações na guia Revisão.","Iniciar Mala Direta na guia Correspondências.","Organizar Tudo na guia Exibição.","Pincel de Formatação na guia Página Inicial.","Referência Cruzada na guia Referências"],"gabarito":"A"},{"n":18,"disciplina":"Informática","tema":"Internet e Navegadores","enunciado":"Numa busca na Internet por meio do Google e do Chrome, que é um dos principais navegadores, é preciso incluir as palavras e/ou termos que devem constar nas páginas a serem selecionadas pelo mecanismo de busca. Entretanto, também é possível determinar palavras que não devem constar no resultado da busca. Assinale a opção que indica como essas palavras devem ser marcadas, para que expressem esse significado de recusa.","alternativas":["Cercar a palavra por um par de aspas duplas.","Grafar a palavra toda com letras maiúsculas e cercá-la por um par de aspas duplas.","Incluir o termo except (ou exceto) imediatamente antes da palavra.","Incluir o termo not (ou não) imediatamente antes da palavra","Incluir um hífen imediatamente antes da palavra"],"gabarito":"E"},{"n":19,"disciplina":"Informática","tema":"Windows","enunciado":"No uso do Windows há um conjunto de atalhos de teclado que são intensamente utilizados devido à praticidade que oferecem. Assinale a opção que apresenta os atalhos que correspondem às operações de Colar, Copiar e Recortar, na ordem.","alternativas":["Ctrl+C, Ctrl+V e Ctrl+X.","Ctrl+C, Ctrl+X e Ctrl+V.","Ctrl+V, Ctrl+C e Ctrl+X.","Ctrl+V, Ctrl+X e Ctrl+C.","Ctrl+X, Ctrl+V e Ctrl+C"],"gabarito":"C"},{"n":20,"disciplina":"Informática","tema":"Microsoft Excel","enunciado":"Considere uma planilha Excel em que as quatro primeiras células da linha 1, da esquerda para a direita, contêm os números 10, 5, 3 e 2, um em cada célula, nessa ordem. Nenhuma outra célula foi preenchida. Assinale a fórmula cujo valor final é 20.","alternativas":["=soma(A1+B2+C3+D4)","=soma(A1+A2 +A3 + A4)","=soma(A1:A4)","=soma(A1:D1)","=soma(A[1:4]) Legislação"],"gabarito":"D"},{"n":21,"disciplina":"Legislação do SUS","tema":"Princípios e Diretrizes do SUS","enunciado":"As diretrizes do Sistema Único de Saúde (SUS), previstas na Constituição Federal de 1988, deram origem a alguns dos princípios do SUS dispostos na Lei Orgânica da Saúde. Assinale a opção que apresenta uma dessas diretrizes.","alternativas":["Descentralização, com direção única em cada esfera de governo.","Divulgação de informações quanto ao potencial dos serviços de saúde e à sua utilização pelo usuário.","Utilização da epidemiologi a para o estabelecimento de prioridades.","Direito à informação, às pessoas assistidas, sobre sua saúde.","Integração em nível executivo das ações de saúde, meio ambiente e saneamento básico"],"gabarito":"A"},{"n":22,"disciplina":"Legislação do SUS","tema":"Lei 8.080/1990 - Princípios e Diretrizes","enunciado":"Uma unidade de saúde recusou -se a prestar atendimento a um morador de rua, com a justificativa de que ele não possuía endereço fixo. Assinale a opção que indica o princípio do SUS que, nesse caso, foi diretamente desrespeitado.","alternativas":["Igualdade.","Universalidade.","Integralidade.","Equidade.","Regionalização"],"gabarito":"B"},{"n":23,"disciplina":"Legislação do SUS","tema":"Política Nacional de Promoção da Saúde","enunciado":"Assinale a opção que apresenta um dos objetivos específicos da Politica Nacional de Promoção da Saúde.","alternativas":["Fomentar o planejamento de ações territorializadas de promoção da saúde com base no reconhecimento de contextos locais e no respeito às diversidades.","Apoiar a formação e a educação permanente em promoção da saúde para ampliar o compromisso e a capacidade crítica e reflexiva dos gestores e trabalhadores de saúde.","Estimular a cooperação e a articulaç ão intrassetorial e intersetorial para ampliar a atuação sobre determinantes e condicionantes da saúde.","Ampliar a governança no desenvolvimento de ações de promoção da saúde que sejam sustentáveis nas dimensões política, social, cultural, econômica e ambiental.","Apoiar o desenvolvimento de espaços de produção social e ambientes saudáveis, favoráveis ao desenvolvimento humano e ao bem-viver"],"gabarito":"E"},{"n":24,"disciplina":"Legislação do SUS","tema":"Política Nacional de Promoção da Saúde","enunciado":"De acordo com os eixos operacionais da Política Nacional de Promoção da Saúde, o “compartilhamento de planos, de metas, de recursos e de objetivos comuns entre os diferentes setores e entre as diferentes áreas do mesmo setor ”, diz respeito à","alternativas":["territorialização.","educação e formação.","vigilância, monitoramento e avaliação.","articulação e cooperação intrassetorial e intersetorial.","produção e disseminação de conhecimentos e saberes."],"gabarito":"D"},{"n":25,"disciplina":"Enfermagem","tema":"Política Nacional de Humanização","enunciado":"Assinale a opção que corresponde a um dos princípios da Política Nacional de Humanização (PNH).","alternativas":["Ambiência.","Acolhimento.","Transversalidade.","Gestão participativa e cogestão","Defesa dos direitos dos usuários."],"gabarito":"C"},{"n":26,"disciplina":"Enfermagem","tema":"Controle de Infecção e Biossegurança","enunciado":"Considerando as medidas de prevenção de infecção estabelecidas pela ANVISA, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O tempo adequado de permanência do cateter umbilical venoso é de, no máximo, 20 dias, pois os riscos de infecção aumentam com o uso em períodos mais prolongados. ( ) Deve-se administrar profilaxia antimicrobiana antes da inserção de qualquer cateter ou durante a permanência dos dispositivos em paciente com longo tempo de internação. ( ) Recomenda-se trocar o equipo e o dispositivo complementar de nutrição parenteral a cada bolsa. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["F – V – F.","V – F – V.","F – F – V.","V – V – F.","V – V – V"],"gabarito":"C"},{"n":27,"disciplina":"Enfermagem","tema":"Centro de Material e Esterilização (CME)","enunciado":"Acerca das normas e rotinas para o processamento de produtos para a saúde, assinale a afirmativa correta.","alternativas":["A realização do teste de Bowie & Dick é obrigatória em todos os ciclos de esterilização da autoclave.","O uso de estufas para a esterilização de produtos para saúde é permitido em casos de emergência.","A lavadora ultrassônica é um equipamento automatizado de limpeza que utiliza o princípio da cavitação.","O Integrador Químico Classe 5 é um indicador projetado para reagir com até duas variáveis críticas.","O uso de caixas metálicas sem furos só é permitido na esterilização de produtos de conformação não complexa"],"gabarito":"C"},{"n":28,"disciplina":"Enfermagem","tema":"Epidemiologia e Vigilância em Saúde","enunciado":"Diante da ocorrência de um caso suspeito ou confirmado de dengue, o profissional responsável deverá realizar a notificação compulsória em até","alternativas":["5 dias.","7 dias.","10 dias.","12 horas.","24 horas"],"gabarito":"B"},{"n":29,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"Nos últimos meses houve um aumento significativo de síndrome gripal em crianças. Entre os sinais de gravidade dessa síndrome está a(o)","alternativas":["coriza.","tosse persistente.","obstrução nasal.","desconforto respiratório.","febre de início súbito"],"gabarito":"D"},{"n":30,"disciplina":"Enfermagem","tema":"Fundamentos e Semiotécnica","enunciado":"Com base nos protocolos de controle e monitoramento dos sinais vitais, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O pulso apical é verificado no ápice do coração, na a ltura do 5º espaço intercostal esquerdo, e é o mais recomendado pra recém-nascidos. ( ) Um paciente adulto classificado como pré -hipertenso é aquele cuja pressão arterial sistólica varia de 130 a 139mmHg. ( ) Um paciente adulto com frequência respirat ória de 30mrm é considerado taquipneico. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["V – V – V.","F – V – F.","V – F – V.","F – F – F.","F – F – V"],"gabarito":"A"},{"n":31,"disciplina":"Enfermagem","tema":"Centro Cirúrgico","enunciado":"Sobre os cuidados com os curativos no pós -operatório de um paciente adulto, analise as afirmativas a seguir. I. É recomendado que o primeiro curativo permaneça por até 48 horas, se não houver contraindicação, presença de dreno, exsudato excessivo e retirada acidental do curativo. II. O curativo nos drenos deve ser isolado do curativo da ferida operatória, sempre que possível, e trocado todas as vezes que apresentar umidade. III. Um curativo com filme transparente diretamente sobre a ferida operatória pode permanecer por até 10 dias, independente da localização da f erida e do volume de drenagem. Está correto o que se afirma em","alternativas":["I, apenas.","II, apenas.","III, apenas.","I e II, apenas.","II e III, apenas"],"gabarito":"D"},{"n":32,"disciplina":"Enfermagem","tema":"Fundamentos e Semiotécnica","enunciado":"Assinale a opção que corresponde ao dispositivo mais indicado para um paciente adulto, com hipoxemia leve, que necessita receber um fluxo baixo de O 2, com concentrações que podem variar de 23% a 44%.","alternativas":["Cateter nasal.","Máscara simples.","Máscara de Venturi.","Máscara não reinalante.","Máscara de reinalação parcial."],"gabarito":"A"},{"n":33,"disciplina":"Enfermagem","tema":"Fundamentos e Semiotécnica","enunciado":"Durante a assistência a um paciente, foi necessário efetuar a coleta de sangue para realização de alguns exames laboratoriais. Com base nas orientações acerca desse procedimento, analise as afirmativas a seguir e assinale (V) para a verdade ira e (F) para a falsa. ( ) As veias basílica mediana e a cefálica são as mais utilizadas para a coleta de sangue, sendo que a basílica mediana é a melhor opção, pois a cefálica é mais propensa à formação de hematomas. ( ) Na coleta múltipla com sistem a a vácuo, os tubos contendo gel separador podem causar interferência nos testes de coagulação e, por isso, os tubos sem aditivos devem ser usados antes dos tubos destinados aos testes de coagulação. ( ) Nas coletas realizadas com seringa e agulha, para transferir o sangue para os tubos de coleta a vácuo, deve -se puncionar a rolha e aplicar pressão no êmbolo até preencher um terço do tubo. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["F – V – F.","V – V – F.","F – F – F.","V – V – V.","F – V – V"],"gabarito":"B"},{"n":34,"disciplina":"Enfermagem","tema":"Fundamentos e Semiotécnica","enunciado":"Sobre a coleta de materiais para exame, segundo as orientações do Ministério da Saúde, assinale a afirmativa correta.","alternativas":["A coleta de secreção uretral deve ser realizada de preferência pela manhã, após a primeira micção.","Nos exames de coprocultura, se a amostra não for enviada ao laboratório em 1 (uma) hora, deve ser conservada em geladeira a 4C por, no máximo, 36 horas.","O paciente, para coleta da primeira amostra de escarro, deve estar em jejum mínimo de 6 (seis) horas e não realizar higiene oral.","A coleta de urina para urocultura deve ser realizada durante 24 horas, desprezando somente o primeiro jato e coletando o restante.","Para coleta de amostra da orofaringe, deve -se coletar swab na área posterior da faringe e tonsilas, evitando tocar na língua"],"gabarito":"E"},{"n":35,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Acerca do atendimento inicial a um paciente, vítima de trauma (ABCDE do trauma), analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Antes de iniciar a avaliação, deve -se estabilizar a coluna cervical do paciente com suspeita de trauma em que haja risco de lesão de coluna. ( ) O tempo de enchimento capilar é avaliado pressionando o leito ungueal do paciente e observando quanto tempo leva para que a cor volte ao normal; esse tempo deve ser igual ou maior que 2 segundos. ( ) A manobra conhecida como tração mandibular ( Jaw Thrust ) é utilizada em pacientes inconscientes para anteriorizar o osso hioide e levantar a língua junto com a mandíbula. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["V – V – F.","F – F – F.","V – F – V.","F – V – F.","V – V – V"],"gabarito":"C"},{"n":36,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Um paciente adulto apresenta queimaduras que atingem as camadas mais profundas da pele com presença de vermelhidão, bolhas e dor. De acordo com essas características, essas lesões são classificadas como queimaduras de","alternativas":["1º grau.","2º grau.","3º grau.","4º grau.","5º grau"],"gabarito":"B"},{"n":37,"disciplina":"Enfermagem","tema":"Imunização","enunciado":"Assinale a opção que indica, de acordo com as recomendações do Ministério da Saúde, a dose e a via de administração da Vacina Inativada contra Poliomielite (VIP).","alternativas":["1 gota – oral.","2 gotas – oral.","0,25mL – subcutânea.","0,5mL – subcutânea.","0,5mL – intramuscular"],"gabarito":"E"},{"n":38,"disciplina":"Enfermagem","tema":"Epidemiologia e Vigilância em Saúde","enunciado":"Até junho de 2023, o Ministério da Saúde registrou 53 casos de febre maculosa no país. Sobre a febre maculosa, assinale a afirmativa correta.","alternativas":["O hospedeiro primário é o carrapato-estrela.","É causada por uma bactéria do gênero Neisseria.","Os principais vetores são animais silvestres e roedores.","É uma doença infecciosa, febril aguda e de gravidade variável.","Os sintomas mais importantes são febre, náuseas e vômito"],"gabarito":"D"},{"n":39,"disciplina":"Enfermagem","tema":"Ética e Legislação em Enfermagem","enunciado":"Um profissional de Enfermagem praticou um ato de imprudência durante o exercício profissional. Em razão disso, ele pode ser suspenso de suas atividades por um período de até","alternativas":["90 dias.","95 dias.","100 dias.","120 dias.","140 dias"],"gabarito":"A"},{"n":40,"disciplina":"Enfermagem","tema":"Centro Cirúrgico","enunciado":"Considerando os protocolos do Ministério da Saúde e os cuidados de enfermagem nos períodos operatórios, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Quando houver necessidade de tricotomia, recomenda -se que esta seja realizada, no máximo, duas horas antes do procedimento cirúrgico. ( ) A profilaxia antimicrobiana deve ser realizada em até 60 minutos antes da indução anestésica. ( ) Na primeira hora do pós -operatório imediato, os sinais vitais do paciente devem ser verificados a cada 30 minutos. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["F – F – V.","F – V – V.","V – V – V.","F – V – F.","V – F – F."],"gabarito":"E"}]}] as const;
export async function sincronizarFGVSaudeLote2025() {
 const usuario=await prisma.usuario.findFirst({orderBy:{id:"asc"},select:{id:true}});
 if(!usuario)return {inseridas:0,existentes:0,repetidas:0};
 const normalizar=(s:string)=>s.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
 const originais=await prisma.questao.findMany({where:{fonte:FONTE_PROVAS_REAIS},select:{enunciado:true}});
 const hashes=new Set(originais.map(x=>normalizar(x.enunciado)));
 const disciplinas=new Map<string,number>();
 let inseridas=0,existentes=0,repetidas=0;
 for(const prova of LOTES)for(const q of prova.itens){
   const origemId="fgv-"+prova.codigo+"-tipo1-q"+String(q.n).padStart(2,"0");
   if(!q.enunciado.trim()||q.alternativas.length!==5||q.alternativas.some(t=>!t.trim())||
      !["A","B","C","D","E"].includes(q.gabarito)||new Set(q.alternativas.map(t=>t.trim().toLowerCase())).size!==5)
     throw new Error("[fgv-saude-lote] Item inválido "+origemId);
   if(await prisma.questao.findFirst({where:{fonte:FONTE_PROVAS_REAIS,origemId},select:{id:true}})){existentes++;continue;}
   const k=normalizar(q.enunciado);if(hashes.has(k)){repetidas++;continue;}
   let disciplinaId=disciplinas.get(q.disciplina);
   if(!disciplinaId){
     let d=await prisma.disciplina.findFirst({where:{usuarioId:usuario.id,nome:{equals:q.disciplina,mode:"insensitive"}},select:{id:true}});
     if(!d)d=await prisma.disciplina.create({data:{usuarioId:usuario.id,nome:q.disciplina},select:{id:true}});
     disciplinaId=d.id;disciplinas.set(q.disciplina,disciplinaId);
   }
   await prisma.questao.create({data:{
     usuarioId:usuario.id,disciplinaId,fonte:FONTE_PROVAS_REAIS,origemId,tema:q.tema,dificuldade:"medio",
     banca:"FGV",ano:prova.ano,cargo:prova.cargo,orgao:prova.orgao,fonteUrl:prova.prova,enunciado:q.enunciado,
     explicacao:"FGV, "+prova.cargo+", "+prova.ano+", prova Tipo 1, questão "+q.n+". Gabarito definitivo: "+
       q.gabarito+". Caderno: "+prova.prova+" | Gabarito: "+prova.gabarito,
     alternativas:{create:q.alternativas.map((texto,i)=>({texto:"ABCDE"[i]+") "+texto,correta:"ABCDE"[i]===q.gabarito}))}
   }});
   inseridas++;hashes.add(k);
 }
 console.log("[fgv-saude-lote-2025] "+inseridas+" inseridas; "+existentes+" existentes; "+repetidas+" duplicadas ignoradas.");
 return {inseridas,existentes,repetidas};
}
